const items = $input.all();
const results = [];
const cutoff = new Date(Date.now() - 12 * 60 * 60 * 1000);

const feedMeta = $('RSS Feeds List').all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const country = feedMeta[i]?.json.country || '?';
  const source  = feedMeta[i]?.json.source  || '?';
  const xml = item.json.data || '';

  const itemBlocks = [...xml.matchAll(/<item[^>]*>([\s\S]*?)<\/item>/gi)];

  for (const block of itemBlocks) {
    const content = block[1];

    const titleMatch = content.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/);
    const linkMatch  = content.match(/<link>([\s\S]*?)<\/link>/) ||
                       content.match(/<link[^>]+href=["']([^"']+)["']/);
    const dateMatch  = content.match(/<pubDate>([\s\S]*?)<\/pubDate>/) ||
                       content.match(/<published>([\s\S]*?)<\/published>/) ||
                       content.match(/<updated>([\s\S]*?)<\/updated>/);
    const descMatch  = content.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/);

    if (!titleMatch) continue;

    const title = titleMatch[1].trim()
      .replace(/&#\d+;/g, '').replace(/&[a-z]+;/gi, '')
      .replace(/\uFFFD/g, '').replace(/[\u200B-\u200D\uFEFF]/g, '');
    const link    = linkMatch  ? linkMatch[1].trim()              : '';
    const dateStr = dateMatch  ? dateMatch[1].trim()              : '';
    const desc    = descMatch  ? descMatch[1].trim().substring(0, 200) : '';

    if (dateStr) {
      const pubDate = new Date(dateStr);
      if (!isNaN(pubDate) && pubDate < cutoff) continue;
    }

    results.push({ title, link: link.split('?')[0], country, source, desc });
  }
}

const forLLM = results.map((r, idx) =>
  `[${idx + 1}] [${r.country} \u2022 ${r.source}] ${r.title}`
).join('\n');

const mapping = results.map((r, idx) => ({
  id: idx + 1,
  title: r.title,
  link: r.link,
  country: r.country,
  source: r.source
}));

return [{ json: { forLLM, mapping, total: results.length } }];

