function extractText(xml, tag) {
  const pattern = '<' + tag + '[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/' + tag + '>';
  const m = xml.match(new RegExp(pattern, 'i'));
