  const isAtom = /<entry[\s>]/i.test(xml);
  const tag = isAtom ? 'entry' : 'item';
  const blocks = [...xml.matchAll(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'gi'))];

  for (const block of blocks) {
    const c = block[1];
    let title = extractText(c, 'title');
