    let pubDate = '';
    const modMatch = c.match(/<modtime>([\s\S]*?)<\/modtime>/);
    if (modMatch) {
      const raw = modMatch[1].trim();
      if (raw.length >= 8) pubDate = raw.substring(0,4) + '-' + raw.substring(4,6) + '-' + raw.substring(6,8);
