const raw = $input.first().json.text || '';
const mappingRaw = $('📋 Forum Aggregate').first().json.mapping;
const mapping = mappingRaw ? JSON.parse(mappingRaw) : [];

if (raw.trim().toUpperCase() === 'NONE' || !raw.trim()) {
  return [{ json: { forumText: '🔍 Новых форумов и конференций не найдено.', urls: [], hasResults: false } }];
}

const byId = {};
for (const m of mapping) byId[m.id] = m;

// Парсер русских дат
const monthMap = {
  'января':1,'февраля':2,'марта':3,'апреля':4,'мая':5,'июня':6,
  'июля':7,'августа':8,'сентября':9,'октября':10,'ноября':11,'декабря':12,
  'январь':1,'февраль':2,'март':3,'апрель':4,'май':5,'июнь':6,
  'июль':7,'август':8,'сентябрь':9,'октябрь':10,'ноябрь':11,'декабрь':12
};

function parseRuDate(str) {
  if (!str) return null;
  // "07 апреля 2026" или "7 мая 2026"
  const m = str.match(/(\d{1,2})\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)\s+(\d{4})/i);
  if (m) return new Date(parseInt(m[3]), monthMap[m[2].toLowerCase()] - 1, parseInt(m[1]));
  // "01.10.2026" или "1.10.2026"
  const m2 = str.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  if (m2) return new Date(parseInt(m2[3]), parseInt(m2[2]) - 1, parseInt(m2[1]));
  // Диапазон "1–3 октября 2026" — берём последний день
  const m3 = str.match(/\d{1,2}[–\-]\s*(\d{1,2})\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)\s+(\d{4})/i);
  if (m3) return new Date(parseInt(m3[3]), monthMap[m3[2].toLowerCase()] - 1, parseInt(m3[1]));
  return null;
}

const today = new Date();
today.setHours(0, 0, 0, 0);

const lines = [];
const urls = [];
const seenEvents = new Set();

for (const line of raw.split('\n').filter(l => l.trim())) {
  const parts = line.split('|').map(p => p.trim());
  if (parts.length < 2) continue;
  const n = parseInt(parts[0], 10);
  if (isNaN(n) || !byId[n]) continue;
  const m = byId[n];
  const eventName = parts[1] || m.title;
  const eventDate = parts[2] || '';
  const eventCity = parts[3] || '';
  const eventSrc = parts[4] || '';

  // Фильтрация по дате — отбрасываем прошедшие
  const parsed = parseRuDate(eventDate);
  if (parsed && parsed < today) continue;

  const normName = eventName.toLowerCase().replace(/[^а-яёa-z0-9]/g, '').replace(/(2026|2025)/g, '').trim();
  if (seenEvents.has(normName)) continue;
  seenEvents.add(normName);

  let displayLine = `• <a href="${m.link}">${eventName}</a>`;
  if (eventDate && eventDate !== 'Дата не указана') displayLine += ` — ${eventDate}`;
  if (eventCity && eventCity !== 'Не указан') displayLine += ` 📍${eventCity}`;
  if (eventSrc) displayLine += ` [${eventSrc}]`;

  lines.push(displayLine);
  urls.push(m.link);
}

let forumText = lines.length > 0
  ? '🔍 <b>Форумы и конференции по ИИ</b>\n\n' + lines.join('\n')
  : '🔍 Новых форумов и конференций не найдено.';

// Обрезка до лимита Telegram, по целым строкам
if (forumText.length > 3900) {
  const allLines = forumText.split('\n');
  let result = allLines[0] + '\n' + allLines[1];
  for (let i = 2; i < allLines.length; i++) {
    if ((result + '\n' + allLines[i]).length > 3900) break;
    result += '\n' + allLines[i];
  }
  forumText = result;
